INSERT INTO collection_pages VALUES('b7065bb62d955c121a9636275f93726340a44d98b8ae2679bbbd78b35726603c','4fae7e67bb8e27543f2efa996fa585e267a828a3a15667ec0e5f5d426fa257e1','{"hasNext":false,"items":[{"author":{"account":{"login":"claude","providerType":"User"},"email":"noreply@anthropic.com","name":"Claude"},"authoredDate":"2026-03-02T04:11:03Z","committedDate":"2026-03-02T04:11:03Z","committer":{"account":{"login":"claude","providerType":"User"},"email":"noreply@anthropic.com","name":"Claude"},"observedAt":"2026-10-08T22:01:45.203Z","repositoryId":1170259226,"sha":"ebfeb1e71615116f2bac57b9524cc5b6f048cae9"}],"observedAt":"2026-10-08T22:01:45.203Z","raw":[{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/81847?v=4","events_url":"https://api.github.com/users/claude/events{/privacy}","followers_url":"https://api.github.com/users/claude/followers","following_url":"https://api.github.com/users/claude/following{/other_user}","gists_url":"https://api.github.com/users/claude/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/claude","id":81847,"login":"claude","node_id":"MDQ6VXNlcjgxODQ3","organizations_url":"https://api.github.com/users/claude/orgs","received_events_url":"https://api.github.com/users/claude/received_events","repos_url":"https://api.github.com/users/claude/repos","site_admin":false,"starred_url":"https://api.github.com/users/claude/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/claude/subscriptions","type":"User","url":"https://api.github.com/users/claude","user_view_type":"public"},"comments_url":"https://api.github.com/repos/jdinsh/File-preview/commits/ebfeb1e71615116f2bac57b9524cc5b6f048cae9/comments","commit":{"author":{"date":"2026-03-02T04:11:03Z","email":"noreply@anthropic.com","name":"Claude"},"comment_count":0,"committer":{"date":"2026-03-02T04:11:03Z","email":"noreply@anthropic.com","name":"Claude"},"message":"feat: implement File Preview MFE with Module Federation\n\nBuilds a self-contained React + Vite micro-frontend that previews PDF,\nimage, DOCX, XLSX, PPTX, code/text files in-browser with no backend\ndependency. Exposed as an ESM Module Federation remote consumable by\nAngular (via @angular-architects/module-federation) and React hosts.\n\nKey decisions:\n- @module-federation/vite for MF plugin (actively maintained, Angular-compatible)\n- react-pdf + pdfjs-dist for PDF rendering (Web Worker, no UI blocking)\n- docx-preview for DOCX (superior fidelity over mammoth)\n- xlsx@0.18.5 for XLSX (last MIT-licensed SheetJS version)\n- Google Docs Viewer iframe for PPTX URLs; placeholder for Blob sources\n- prism-react-renderer for syntax-highlighted code/text\n- CSS Modules + cssCodeSplit:false for zero style bleed into host apps\n\nhttps://claude.ai/code/session_01SGykVfYJKBbk7HqkZFRJpV","tree":{"sha":"81497454e379ee9d15c17b3226a2c9f2c85c8d44","url":"https://api.github.com/repos/jdinsh/File-preview/git/trees/81497454e379ee9d15c17b3226a2c9f2c85c8d44"},"url":"https://api.github.com/repos/jdinsh/File-preview/git/commits/ebfeb1e71615116f2bac57b9524cc5b6f048cae9","verification":{"payload":"tree 81497454e379ee9d15c17b3226a2c9f2c85c8d44\nauthor Claude <noreply@anthropic.com> 1772424663 +0000\ncommitter Claude <noreply@anthropic.com> 1772424663 +0000\n\nfeat: implement File Preview MFE with Module Federation\n\nBuilds a self-contained React + Vite micro-frontend that previews PDF,\nimage, DOCX, XLSX, PPTX, code/text files in-browser with no backend\ndependency. Exposed as an ESM Module Federation remote consumable by\nAngular (via @angular-architects/module-federation) and React hosts.\n\nKey decisions:\n- @module-federation/vite for MF plugin (actively maintained, Angular-compatible)\n- react-pdf + pdfjs-dist for PDF rendering (Web Worker, no UI blocking)\n- docx-preview for DOCX (superior fidelity over mammoth)\n- xlsx@0.18.5 for XLSX (last MIT-licensed SheetJS version)\n- Google Docs Viewer iframe for PPTX URLs; placeholder for Blob sources\n- prism-react-renderer for syntax-highlighted code/text\n- CSS Modules + cssCodeSplit:false for zero style bleed into host apps\n\nhttps://claude.ai/code/session_01SGykVfYJKBbk7HqkZFRJpV\n","reason":"valid","signature":"-----BEGIN SSH SIGNATURE-----\nU1NIU0lHAAAAAQAAADMAAAALc3NoLWVkMjU1MTkAAAAgrLzsfFISF4by8Q+FKz27YpkK1USsBB+m\namu1QkJnbDsAAAADZ2l0AAAAAAAAAAZzaGE1MTIAAABTAAAAC3NzaC1lZDI1NTE5AAAAQIE1RyjS\nWBuk/T37wJVygN8HUgYntixioSmt3RdSbILAt5GzsYucy30kklohYIlE6RIjVBXGlRif8EHcuNFv\ndw0=\n-----END SSH SIGNATURE-----","verified":true,"verified_at":"2026-03-02T04:11:13Z"}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/81847?v=4","events_url":"https://api.github.com/users/claude/events{/privacy}","followers_url":"https://api.github.com/users/claude/followers","following_url":"https://api.github.com/users/claude/following{/other_user}","gists_url":"https://api.github.com/users/claude/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/claude","id":81847,"login":"claude","node_id":"MDQ6VXNlcjgxODQ3","organizations_url":"https://api.github.com/users/claude/orgs","received_events_url":"https://api.github.com/users/claude/received_events","repos_url":"https://api.github.com/users/claude/repos","site_admin":false,"starred_url":"https://api.github.com/users/claude/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/claude/subscriptions","type":"User","url":"https://api.github.com/users/claude","user_view_type":"public"},"html_url":"https://github.com/jdinsh/File-preview/commit/ebfeb1e71615116f2bac57b9524cc5b6f048cae9","node_id":"C_kwDORcC9GtoAKGViZmViMWU3MTYxNTExNmYyYmFjNTdiOTUyNGNjNWI2ZjA0OGNhZTk","parents":[],"sha":"ebfeb1e71615116f2bac57b9524cc5b6f048cae9","url":"https://api.github.com/repos/jdinsh/File-preview/commits/ebfeb1e71615116f2bac57b9524cc5b6f048cae9"}],"requestUrl":"https://api.github.com/repos/jdinsh/File-preview/commits?per_page=100&page=1&sha=ebfeb1e71615116f2bac57b9524cc5b6f048cae9&since=2025-03-31T23%3A59%3A59.000Z&until=202